try { if (YCLOUD_SENT_FILE && require('fs').existsSync(YCLOUD_SENT_FILE)) for (const [k, v] of JSON.parse(require('fs').readFileSync(YCLOUD_SENT_FILE, 'utf8'))) ycloudSentMedia.set(k, v); } catch (_) {}
